import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"MySQL RLS + Multi-Tenant SaaS — Quality Report (v1.26-3)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/db/mysql-rls-tenant-app.md","filePath":"quality-reports/db/mysql-rls-tenant-app.md"}'),r={name:"quality-reports/db/mysql-rls-tenant-app.md"};function s(n,e,i,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="mysql-rls-multi-tenant-saas-—-quality-report-v1-26-3" tabindex="-1">MySQL RLS + Multi-Tenant SaaS — Quality Report (v1.26-3) <a class="header-anchor" href="#mysql-rls-multi-tenant-saas-—-quality-report-v1-26-3" aria-label="Permalink to &quot;MySQL RLS + Multi-Tenant SaaS — Quality Report (v1.26-3)&quot;">​</a></h1><p>Dogfood: <a href="./../../../examples/dogfood-mysql-rls-tenant-app/"><code>examples/dogfood-mysql-rls-tenant-app</code></a>. Package under exercise: <a href="./../../../packages/orm/"><code>@kiwa-lab/orm</code></a> (v0.9) RLS axis.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The dogfood exercises the 4 MySQL 8 RLS + multi-tenant patterns the orm package promises in v0.9:</p><ol><li><strong>Tenant_id auto-injection on write</strong> — every write goes through an RLS gate that mounts a <code>organizations_tenant_isolation</code> policy on the <code>organizations</code> table (tenant column <code>tenant_id</code>), then enforces the policy before touching the store (<code>src/rls/index.ts</code> wraps <code>@kiwa-lab/orm</code>&#39;s <code>createRlsSession</code> / <code>installPolicy</code> / <code>filterTenant</code> / <code>logAudit</code>).</li><li><strong>Cross-tenant read refuse</strong> — an acting tenant&#39;s caller cannot read another tenant&#39;s rows; the refusal returns <code>CROSS_TENANT_REFUSED</code> and appends <code>allowed=false</code> to the audit trail (<code>tryCrossTenantRead</code> in <code>src/rls/index.ts</code>).</li><li><strong><code>bypass_rls</code> role window</strong> — a support role opens a single-shot bypass via <code>withBypass</code>, the RLS session transitions to <code>bypassed</code>, every op inside the window is captured, and the session re-arms to <code>policy-installed</code> on the next non-bypass op via the <code>rearmIfBypassed</code> helper.</li><li><strong>Tamper-evident audit log</strong> — a chain-hash log (<code>src/audit/index.ts</code>) runs <code>sha256</code>-style folded FNV mix over <code>sha256(prev || entryJson)</code> so any middle-insertion breaks every downstream hash; <code>verify</code> reports the first index whose stored hash disagrees with the recomputed hash.</li></ol><p>All 4 patterns are driven end-to-end through a provider-neutral adapter (<code>src/adapters/interface.ts</code>) with mock (<code>src/adapters/mock.ts</code>) and real (<code>src/adapters/real.ts</code>) implementations.</p><h2 id="release-gate-—-7-axis-verdict-mock-trace" tabindex="-1">Release gate — 7 axis verdict (mock trace) <a class="header-anchor" href="#release-gate-—-7-axis-verdict-mock-trace" aria-label="Permalink to &quot;Release gate — 7 axis verdict (mock trace)&quot;">​</a></h2><p>Snapshot from <code>examples/dogfood-mysql-rls-tenant-app/quality-report/fidelity-latest.md</code>, which is generated locally by <code>pnpm -F dogfood-mysql-rls-tenant-app test</code> and is not tracked in the repository (see #1395).</p><table tabindex="0"><thead><tr><th>axis</th><th>value</th><th>gate</th></tr></thead><tbody><tr><td>coverage — line</td><td>92.00%</td><td>PASS</td></tr><tr><td>coverage — branch</td><td>88.00%</td><td>PASS</td></tr><tr><td>coverage — function</td><td>95.00%</td><td>PASS</td></tr><tr><td>test count — total</td><td>35 (behavior 24 + integration 6 + e2e 5)</td><td>PASS</td></tr><tr><td>fidelity — ratio</td><td>100% mock covered (5/5)</td><td>PASS</td></tr><tr><td>perf — p95</td><td>&lt; 1ms per op</td><td>PASS</td></tr><tr><td>mutation — killRate</td><td>73.33% (22/30)</td><td>PASS</td></tr><tr><td><strong>release gate verdict</strong></td><td><strong>PASS</strong></td><td>7 axes evaluated</td></tr></tbody></table><h2 id="real-vs-mock-fidelity" tabindex="-1">Real vs mock fidelity <a class="header-anchor" href="#real-vs-mock-fidelity" aria-label="Permalink to &quot;Real vs mock fidelity&quot;">​</a></h2><p>The 5-op adapter surface reports 5 behavioral divergences under the default <code>MYSQL_KEY=</code> unset configuration — every real op returns <code>MYSQL_ENV_MISSING</code> while the mock op succeeds. These are well-defined divergences: the fidelity harness records them without failing the release gate because the real adapter is scope-boxed to aliveness in v1.26-3. A future v1.26-6 publish milestone can extend <code>makeConnectedRealAdapter</code> with an actual <code>mysql2</code> + Prisma RLS migration runner once the harness is proved on mock.</p><p>When <code>MYSQL_KEY</code> is set (e.g. <code>mysql://user:pass@localhost:3306/kiwa</code>), the adapter runs a DSN aliveness probe and records <code>probe.ok=true</code>, then falls back to <code>REAL_ADAPTER_NOT_IMPLEMENTED</code> for higher-level ops.</p><h2 id="test-map" tabindex="-1">Test map <a class="header-anchor" href="#test-map" aria-label="Permalink to &quot;Test map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>suite</th><th>file</th><th>count</th></tr></thead><tbody><tr><td>tenant + RLS gate contract</td><td><code>tests/tenant-isolation-e2e.spec.ts</code></td><td>7 (T-DMT-001..007)</td></tr><tr><td>bypass_rls + audit trail</td><td><code>tests/bypass-rls-refuse-e2e.spec.ts</code></td><td>5 (T-DMB-001..005)</td></tr><tr><td>audit chain invariants</td><td><code>tests/audit-log-e2e.spec.ts</code></td><td>6 (T-DMA-001..006)</td></tr><tr><td>5-op mock E2E</td><td><code>tests/e2e-mock-mode.test.ts</code></td><td>7 (T-DME-M-001..007)</td></tr><tr><td>fidelity harness</td><td><code>tests/fidelity-report.test.ts</code></td><td>3 (T-DMF-001..003)</td></tr><tr><td>fidelity emit</td><td><code>tests/emit-fidelity-report.test.ts</code></td><td>1 (T-DME-EM-001)</td></tr><tr><td>real env-gated probe</td><td><code>tests/real-adapter-probe.test.ts</code></td><td>5 (T-DMR-ENV-001..005)</td></tr><tr><td>3-layer perf</td><td><code>tests/perf/dogfood-mysql-rls-tenant-app.perf.ts</code></td><td>1</td></tr></tbody></table><h2 id="extension-roadmap" tabindex="-1">Extension roadmap <a class="header-anchor" href="#extension-roadmap" aria-label="Permalink to &quot;Extension roadmap&quot;">​</a></h2><ul><li>v1.26-6 publish milestone — extend <code>makeConnectedRealAdapter</code> with a real <code>mysql2</code> + Prisma RLS migration runner so the fidelity gap closes and behavioural divergences drop below 5.</li><li>follow-up — add testcontainers MySQL 8 harness under a <code>MYSQL_KEY</code> env-gate so KIWA_MODE=real can spin up a broker in CI without a pre-provisioned instance.</li><li>follow-up — swap the FNV-folded chain-hash for HMAC-SHA256 with a KMS-managed key so the tamper-evident log meets a real audit requirement rather than a single-purpose invariant.</li></ul>',16)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
